import {appearance} from '../../ui/semantics.js';
import {esc,safeUrl}from'../../ui/format.js';import{TYPES}from'../../core/model.js';
export function libraryView({m,catalog,query,category,libraryMode}){const filtered=catalog.filter(t=>(libraryMode==='all'||(libraryMode==='commercial'?t.commercial:!t.commercial))&&(!category||t.category===category)&&(t.name+' '+t.category+' '+t.description).toLowerCase().includes(query.toLowerCase()));return `<section class="page-intro"><div><div class="eyebrow">ECHIPAMENTE · OAMENI · PROCESE</div><h1>Începe cu un model real.</h1><p>Specificații documentate. Parametri editabili. Același obiect în toate vederile.</p></div><span class="badge">${catalog.filter(t=>t.commercial).length} modele comerciale</span></section><div class="library-tools"><label class="searchbox"><span>⌕</span><input id="library-search" placeholder="Caută producător, utilaj sau test…" value="${esc(query)}"></label><select id="library-category" aria-label="Categorie bibliotecă"><option value="">Toate categoriile</option>${[...new Set(catalog.map(t=>t.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="library-mode" aria-label="Tip bibliotecă"><option value="commercial" ${libraryMode==='commercial'?'selected':''}>Modele comerciale</option><option value="generic" ${libraryMode==='generic'?'selected':''}>Procese & roluri generice</option><option value="all" ${libraryMode==='all'?'selected':''}>Toată biblioteca</option></select></div><div class="library-note">${libraryMode==='commercial'?'Specificațiile se referă la configurația indicată. Ciclul de producție se stabilește pentru piesa și procesul tău.':'Rolurile și procesele generice nu au performanțe universale. Configurează datele locale înainte de a interpreta rezultatele.'}</div><div class="catalog-grid">${filtered.map(t=>`<article class="panel catalog-card" style="--family-color:${appearance(t).color};--family-tint:${appearance(t).tint}"><div class="catalog-top"><span class="equipment-glyph" aria-hidden="true">${t.type==='robot'?'⌘':['person','team'].includes(t.type)?'♙':t.type==='inspection'?'◎':'▣'}</span><span class="badge ${t.commercial?'':'amber'}">${t.commercial?'Date producător':'De configurat'}</span></div><small class="eyebrow">${esc(t.category)}</small><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="spec-preview">${(t.specs||[]).slice(0,3).map(s=>`<span>${esc(s.name)} <b>${s.value} ${esc(s.unit)}</b></span>`).join('')||`<span>${esc(TYPES[t.type])}<b>Parametri locali</b></span>`}</div>${t.commercial?`<a href="${esc(safeUrl(t.source))}" target="_blank" rel="noopener noreferrer" class="source-link">Fișa producătorului ↗</a>`:'<span class="small muted">Fără valori comerciale atribuite acestui șablon</span>'}<div class="row"><button data-configure="${esc(t.id)}" class="primary">Configurează & adaugă</button>${['machine','robot','hardware','tool'].includes(t.type)?`<button data-configure-cell="${esc(t.id)}" title="Creează flux, operație și personal">+ Celulă</button>`:''}</div></article>`).join('')||'<div class="panel empty"><h2>Niciun rezultat</h2><p>Schimbă filtrul sau caută o altă categorie.</p></div>'}</div><h2>Biblioteca mea</h2><div class="catalog-grid">${(m.library||[]).map(t=>`<article class="panel"><h3>${esc(t.name)}</h3><p>${esc(TYPES[t.element.type])}</p><div class="row"><button data-personal="${esc(t.id)}">+ Instanță nouă</button><button data-templatedelete="${esc(t.id)}">Șterge șablon</button></div></article>`).join('')||'<div class="panel"><p>Salvează un element configurat din inspector pentru a-l reutiliza.</p></div>'}</div>`}
